package EnergyCommunity.core.mcpServer.agent.model;

import java.util.Map;

/**
 * Represents a tool invocation requested by the LLM during its reasoning loop.
 *
 * @param callId    Unique tool call identifier generated by the LLM
 * @param toolName  Name of the MCP tool to invoke (e.g. "get_house_status")
 * @param arguments Parsed arguments to pass to the MCP server
 */
public record LlmToolCall(
        String callId,
        String toolName,
        Map<String, Object> arguments
) {
}
